package com.spaceagent.platform.runtime.infrastructure.persistence;
import com.spaceagent.platform.runtime.domain.*;import java.sql.*;import java.util.*;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository @ConditionalOnProperty(prefix="platform",name="persistence",havingValue="postgres") public class PostgresSupervisorRunPolicyRepository implements SupervisorRunPolicyRepository{private final JdbcTemplate jdbc;public PostgresSupervisorRunPolicyRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}public Optional<SupervisorRunPolicy> find(String id){return jdbc.query("SELECT * FROM platform_supervisor_run_policies WHERE agent_run_id=?",(r,n)->new SupervisorRunPolicy(r.getString("agent_run_id"),r.getString("tenant_id"),r.getString("owner_id"),new SupervisorPolicy(SupervisorPolicyMode.valueOf(r.getString("mode")),r.getBoolean("kill_switch"),r.getBoolean("provider_candidate_allowed"),r.getString("policy_hash"),r.getTimestamp("pinned_at").toInstant()),r.getLong("revision")),id).stream().findFirst();}public boolean insertIfAbsent(SupervisorRunPolicy p){return jdbc.update("INSERT INTO platform_supervisor_run_policies(agent_run_id,tenant_id,owner_id,mode,kill_switch,provider_candidate_allowed,policy_hash,pinned_at,revision) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(agent_run_id) DO NOTHING",p.agentRunId(),p.tenantId(),p.ownerId(),p.policy().mode().name(),p.policy().killSwitch(),p.policy().providerCandidateAllowed(),p.policy().policyHash(),Timestamp.from(p.policy().pinnedAt()),p.revision())==1;}}
